import random
from.question import Question

class QuestionBank:
    def __init__(self):
        self.questions = []

    def add_question(self, text, answer, answers):
        self.questions.append(Question(text, answer, answers))

    def get_random_question(self):
        return random.choice(self.questions)

    def get_question_index(self):
        return len(self.questions)

    def __str__(self):
        return "\n\n".join([str(question) for question in self.questions])
